WITH dim_totals AS (SELECT d.city, a.status, COUNT(*) AS rows_total, MIN(a.balance) AS min_balance FROM accounts a LEFT JOIN customers d ON a.customer_id = d.id GROUP BY ROLLUP (d.city, a.status)) SELECT city, status, rows_total, min_balance, CASE WHEN city RLIKE '^(Singapore|Berlin)$' THEN 'EXTENDED' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'CORE' ELSE 'GROUP_A' END AS city_zone FROM dim_totals ORDER BY rows_total DESC;
